<header x-data="Header" class="bg-white shadow-sm sticky top-0 z-50">
<div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
<div class="flex justify-between items-center h-20"><a href="{{ route('frontend.home') }}" class="flex items-center gap-3">
<div class="h-12 w-12 rounded-full bg-[#123A63] flex items-center justify-center"><span class="text-white font-bold text-xl">IP</span></div>
<div>
<h1 class="text-xl font-bold text-[#123A63]">Invest Panjakent</h1><p class="text-xs text-[#667085]">Republic of Tajikistan</p></div></a>
<nav class="hidden lg:flex items-center gap-6">
<template x-for="item in navItems.slice(0, 4)"><a :href="url(item.path)" class="text-sm text-[#1F2933] hover:text-[#123A63] transition-colors"><span x-text="item.name"></span></a></template></nav>
<div class="flex items-center gap-3"><button @click="(() =&gt; setSearchOpen(!searchOpen))($event)" class="p-2 hover:bg-gray-100 rounded-lg transition-colors hidden sm:block"><svg class="h-5 w-5 text-[#667085]" width="24" height="24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><use :href="'#icon-' + (&quot;Search&quot;)"></use></svg></button>
<div class="relative" x-data="{_open:false}" >
<div @click="_open=!_open"><button class="hidden sm:flex items-center gap-2 px-3 py-2 hover:bg-gray-100 rounded-lg transition-colors"><svg class="h-4 w-4 text-[#667085]" width="24" height="24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><use :href="'#icon-' + (&quot;Globe&quot;)"></use></svg><span class="text-sm font-medium text-[#1F2933]"><span x-text="currentLang"></span></span><svg class="h-4 w-4 text-[#667085]" width="24" height="24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><use :href="'#icon-' + (&quot;ChevronDown&quot;)"></use></svg></button></div>
<div x-cloak x-show="_open" @click.outside="_open=false" @keydown.escape.window="_open=false" class="absolute right-0 top-full z-[80] min-w-32 rounded-md border bg-white p-1 shadow-lg">
<template x-for="lang in languages"><button type="button" :class="currentLang === lang.code ? &quot;bg-gray-100&quot; : &quot;&quot;" class="block w-full text-left px-2 py-1.5 text-sm hover:bg-gray-100" @click="(() =&gt; setCurrentLang(lang.code))($event); _open=false"><span x-text="lang.name"></span></button></template></div></div><a href="{{ route('frontend.portal') }}" class="hidden md:flex items-center gap-2 px-4 py-2 border border-[#123A63] text-[#123A63] rounded-lg hover:bg-[#123A63]/5 transition-colors"><svg class="h-4 w-4" width="24" height="24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><use :href="'#icon-' + (&quot;LogIn&quot;)"></use></svg><span class="text-sm">Investor Portal</span></a><a href="{{ route('frontend.submit-interest') }}" class="hidden sm:flex items-center gap-2 px-4 py-2 bg-[#0F8A5F] text-white rounded-lg hover:bg-[#0F8A5F]/90 transition-colors"><svg class="h-4 w-4" width="24" height="24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><use :href="'#icon-' + (&quot;FileText&quot;)"></use></svg><span class="text-sm">Submit Interest</span></a>
<div class="relative" x-data="{_open:false}" x-effect="_open=mobileMenuOpen">
<div @click="_open=!_open"><button class="lg:hidden p-2 hover:bg-gray-100 rounded-lg transition-colors"><svg class="h-6 w-6 text-[#1F2933]" width="24" height="24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><use :href="'#icon-' + (&quot;Menu&quot;)"></use></svg></button></div>
<div x-cloak x-show="_open" @click.outside="_open=false" @keydown.escape.window="_open=false" class="fixed right-0 top-0 bottom-0 w-80 z-[80] bg-white p-6 shadow-xl overflow-y-auto"><button type="button" class="float-right" @click="_open=false" aria-label="Close menu">×</button>
<div>
<h2 class="text-[#123A63]">Menu</h2></div>
<nav class="flex flex-col gap-4 mt-8">
<template x-for="item in navItems"><a :href="url(item.path)" @click="(() =&gt; setMobileMenuOpen(false))($event)" class="text-lg text-[#1F2933] hover:text-[#123A63] transition-colors py-2"><span x-text="item.name"></span></a></template>
<div class="border-t border-gray-200 my-4"></div><a href="{{ route('frontend.portal') }}" @click="(() =&gt; setMobileMenuOpen(false))($event)" class="flex items-center gap-2 text-lg text-[#1F2933] hover:text-[#123A63] transition-colors py-2"><svg class="h-5 w-5" width="24" height="24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><use :href="'#icon-' + (&quot;LogIn&quot;)"></use></svg>Investor Portal </a><a href="{{ route('frontend.submit-interest') }}" @click="(() =&gt; setMobileMenuOpen(false))($event)" class="flex items-center gap-2 px-4 py-3 bg-[#0F8A5F] text-white rounded-lg hover:bg-[#0F8A5F]/90 transition-colors justify-center"><svg class="h-5 w-5" width="24" height="24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><use :href="'#icon-' + (&quot;FileText&quot;)"></use></svg>Submit Interest </a>
<div class="mt-4"><p class="text-sm text-[#667085] mb-2">Language</p>
<div class="flex gap-2">
<template x-for="lang in languages"><button @click="(() =&gt; setCurrentLang(lang.code))($event)" :class="`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${currentLang === lang.code ? &quot;bg-[#123A63] text-white&quot; : &quot;bg-gray-100 text-[#1F2933] hover:bg-gray-200&quot;}`"><span x-text="lang.code"></span></button></template></div></div></nav></div></div></div></div></div>
<template x-if="Boolean(searchOpen)">
<div class="border-t border-gray-200 bg-white">
<div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
<div class="relative"><svg class="absolute left-3 top-1/2 transform -translate-y-1/2 h-5 w-5 text-[#667085]" width="24" height="24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><use :href="'#icon-' + (&quot;Search&quot;)"></use></svg><input type="text" placeholder="Search investment opportunities, sectors, documents..." class="w-full pl-10 pr-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-[#123A63]" autoFocus=""></div></div></div></template>
<div class="sm:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 p-4 z-40"><a href="{{ route('frontend.submit-interest') }}" class="flex items-center justify-center gap-2 w-full px-4 py-3 bg-[#0F8A5F] text-white rounded-lg hover:bg-[#0F8A5F]/90 transition-colors"><svg class="h-5 w-5" width="24" height="24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><use :href="'#icon-' + (&quot;FileText&quot;)"></use></svg><span class="font-medium">Submit Investment Interest</span></a></div></header>